// server/gathering.js — GENERATED by the Neblla no-code matchmaking
// configurator. Edits here are overwritten on the next save while the
// app stays in no-code matchmaking mode. Switch matchmaking to "custom"
// in the dashboard to take ownership of this file.
//
// Rule: count
// Runs on the room's server peer during the wait window between
// rooms.join() and room.start(). No DOM, no neblla.auth.
// ══════════════════════════════════════════════════════════════

const MIN_PLAYERS = 2;
const MAX_PLAYERS = 2;
let started = false;

function start() {
  if (started) return;
  started = true;
  neblla.room.start();
}

// Start as soon as enough players have arrived.
function checkCount() {
  if (neblla.room.users.length >= MIN_PLAYERS) start();
}
neblla.room.on('userJoined', checkCount);
checkCount();

// Hard cap: once the room is full, start immediately.
neblla.room.on('userJoined', () => {
  if (neblla.room.users.length >= MAX_PLAYERS) start();
});

// The presenter can also start early: from client.js with
// neblla.room.start(), or with
// neblla.message.to('server', { type: 'start' }). The same message
// from anyone else is ignored.
neblla.message.on((m) => {
  if (m.to !== 'server') return;
  const presenter = neblla.room.presenter;
  if (!presenter || m.from !== presenter.id) return;
  if (m.data && m.data.type === 'start') start();
});
